sn_aia_tool.script:
(function(inputs) {

    var result = {
        total_complaints: 0,
        by_use_case: {},
        by_mess_hall: {},
        by_meal_type: {},
        by_problem_type: {}
    };

    var gr = new GlideRecord('x_snc_campus_foo_1_food_complaint');
    gr.query();

    while (gr.next()) {

        result.total_complaints++;

        var useCase = gr.getDisplayValue('use_case') || 'Not specified';
        var messHall = gr.getDisplayValue('mess_hall') || 'Not specified';
        var mealType = gr.getDisplayValue('meal_type') || 'Not specified';
        var problemType = gr.getValue('problem_type') || 'Not specified';

        if (!result.by_use_case[useCase])
            result.by_use_case[useCase] = 0;
        result.by_use_case[useCase]++;

        if (!result.by_mess_hall[messHall])
            result.by_mess_hall[messHall] = 0;
        result.by_mess_hall[messHall]++;

        if (!result.by_meal_type[mealType])
            result.by_meal_type[mealType] = 0;
        result.by_meal_type[mealType]++;

        if (!result.by_problem_type[problemType])
            result.by_problem_type[problemType] = 0;
        result.by_problem_type[problemType]++;
    }

    return {
        analytics_data: JSON.stringify(result)
    };

})(inputs);
